:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --bg: #F3F5FA;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --info-bg: #DCE4F3;
  --warn: #B45309;
  --warn-bg: #FEF3C7;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --ok: #15803D;
  --ok-bg: #DCFCE7;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
}

body {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px 16px;
}

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.head h2 {
  font-size: 17px;
  margin: 0;
}

.head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.btn {
  flex: none;
  height: 32px;
  padding: 0 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--primary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  border-color: var(--accent);
}

.btn:disabled {
  opacity: 0.55;
  cursor: default;
}

/* ---------------------------------------------------------------- ringkasan */
.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 74px;
  padding: 12px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid var(--border);
  border-radius: var(--radius);
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.stat:hover, .stat:focus-visible {
  border-color: var(--accent);
  outline: none;
}

.stat .value {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
}

.stat .label {
  font-size: 12.5px;
  color: var(--muted);
}

.stat.tone-info {
  border-left-color: var(--accent);
}

.stat.tone-warn {
  border-left-color: var(--warn);
}

.stat.tone-warn .value {
  color: var(--warn);
}

.stat.tone-ok {
  border-left-color: var(--ok);
}

/* ---------------------------------------------------------------- bagian */
.sections {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  align-items: start;
}

.sections.cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.card {
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.25);
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}

.card h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 15px;
  color: var(--primary);
}

.count {
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--surface-alt);
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.note {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12.5px;
}

.list {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
}

.task {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 6px;
  border: 0;
  border-top: 1px solid var(--surface-alt);
  background: transparent;
  text-align: left;
  font: inherit;
  color: inherit;
}

.task:first-child {
  border-top: 0;
}

button.task {
  cursor: pointer;
}

button.task:hover, button.task:focus-visible {
  background: var(--bg);
  outline: none;
}

.task-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.task-title {
  font-weight: 600;
  color: var(--primary);
  overflow-wrap: anywhere;
}

.task-meta {
  font-size: 12.5px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.task-flags {
  flex: none;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  max-width: 46%;
}

.flag {
  padding: 2px 9px;
  border-radius: 999px;
  background: var(--surface-alt);
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
}

.flag.tone-info {
  background: var(--info-bg);
  color: var(--primary);
}

.flag.tone-warn {
  background: var(--warn-bg);
  color: var(--warn);
}

.flag.tone-danger {
  background: var(--danger-bg);
  color: var(--danger);
}

.flag.tone-ok {
  background: var(--ok-bg);
  color: var(--ok);
}

.chev {
  flex: none;
  color: var(--muted);
}

button.task:hover .chev {
  color: var(--accent);
}

.more {
  align-self: flex-start;
  margin-top: 6px;
  padding: 4px 6px;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.none {
  margin: 10px 0 2px;
  color: var(--muted);
  font-size: 13px;
}

.empty {
  padding: 24px;
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: var(--radius);
}

.skeleton {
  cursor: default;
  border-color: transparent;
  background: linear-gradient(90deg, #eef1f7 25%, #f7f9fc 50%, #eef1f7 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s infinite;
}

@keyframes shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
@media (max-width: 760px) {
  .sections.cols-2 {
    grid-template-columns: 1fr;
  }
  .task-flags {
    max-width: 38%;
  }
}

srcDoc.js:
// cwWorklist — daftar "Tugas Saya" di Beranda (ringkasan + bagian berisi tugas yang bisa diklik). Hanya tampilan.
// Model masuk: { loaded, loading, title, subtitle, columns, stats: [{ key, value, label, tone }],
//   sections: [{ key, title, note, empty, hideWhenEmpty, items: [{ title, meta, flags: [{ text, tone, hint }], target, params }] }] }
// Event keluar: onOpen (setelah appsmith.updateModel({ target, params })), onRefresh.

const $ = id => document.getElementById(id);
const LIMIT = 6; // item per bagian sebelum "Tampilkan semua"
const expanded = {}; // key bagian -> sudah "Tampilkan semua"
const TONES = ['info', 'warn', 'danger', 'ok'];
function esc(text) {
  const div = document.createElement('div');
  div.textContent = text == null ? '' : String(text);
  return div.innerHTML;
}
function applyTheme(theme) {
  const t = theme || {};
  const root = document.documentElement.style;
  if (t.primaryColor) root.setProperty('--primary', t.primaryColor);
  if (t.borderRadius) root.setProperty('--radius', t.borderRadius);
  if (t.fontFamily && t.fontFamily !== 'System Default') {
    root.setProperty('--font', `${t.fontFamily}, "Segoe UI", Arial, sans-serif`);
  }
}
function toneClass(tone) {
  return TONES.includes(tone) ? ` tone-${tone}` : '';
}
function open(item) {
  appsmith.updateModel({
    target: item.target,
    params: item.params || {}
  });
  appsmith.triggerEvent('onOpen');
}
function goTo(key) {
  const el = document.getElementById('sec-' + key);
  if (el) el.scrollIntoView({
    behavior: 'smooth',
    block: 'start'
  });
}
function statEl(stat) {
  const value = Number(stat.value) || 0;
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'stat' + (value > 0 ? toneClass(stat.tone) : '');
  btn.innerHTML = `<span class="value">${esc(value.toLocaleString('id-ID'))}</span><span class="label">${esc(stat.label)}</span>`;
  btn.addEventListener('click', () => goTo(stat.key));
  return btn;
}
function taskEl(item) {
  const clickable = !!item.target;
  const el = document.createElement(clickable ? 'button' : 'div');
  if (clickable) el.type = 'button';
  el.className = 'task';
  const flags = (Array.isArray(item.flags) ? item.flags : []).map(f => `<span class="flag${toneClass(f.tone)}"${f.hint ? ` title="${esc(f.hint)}"` : ''}>${esc(f.text)}</span>`).join('');
  el.innerHTML = `
    <span class="task-main">
      <span class="task-title">${esc(item.title)}</span>
      ${item.meta ? `<span class="task-meta">${esc(item.meta)}</span>` : ''}
    </span>
    ${flags ? `<span class="task-flags">${flags}</span>` : ''}
    ${clickable ? '<span class="chev" aria-hidden="true">→</span>' : ''}`;
  if (clickable) el.addEventListener('click', () => open(item));
  return el;
}
function sectionEl(section, rerender) {
  const items = Array.isArray(section.items) ? section.items : [];
  const card = document.createElement('section');
  card.className = 'card';
  card.id = 'sec-' + section.key;
  card.innerHTML = `<h3>${esc(section.title)}${items.length ? ` <span class="count">${items.length}</span>` : ''}</h3>` + (section.note ? `<p class="note">${esc(section.note)}</p>` : '');
  if (!items.length) {
    card.insertAdjacentHTML('beforeend', `<p class="none">${esc(section.empty || 'Tidak ada.')}</p>`);
    return card;
  }
  const list = document.createElement('div');
  list.className = 'list';
  const shown = expanded[section.key] ? items : items.slice(0, LIMIT);
  shown.forEach(item => list.appendChild(taskEl(item)));
  card.appendChild(list);
  if (items.length > LIMIT) {
    const more = document.createElement('button');
    more.type = 'button';
    more.className = 'more';
    more.textContent = expanded[section.key] ? 'Tampilkan lebih sedikit' : `Tampilkan semua (${items.length})`;
    more.addEventListener('click', () => {
      expanded[section.key] = !expanded[section.key];
      rerender();
    });
    card.appendChild(more);
  }
  return card;
}
let current = {};
function render(model) {
  current = model || {};
  const m = current;
  const scroller = document.scrollingElement || document.documentElement;
  const keepTop = scroller.scrollTop;
  $('title').textContent = m.title || 'Tugas Saya';
  $('subtitle').textContent = m.subtitle || '';
  $('subtitle').hidden = !m.subtitle;
  $('refresh').disabled = !!m.loading;
  $('refresh').textContent = m.loading ? 'Memuat…' : '↻ Muat ulang';
  const loaded = !!m.loaded;
  const stats = Array.isArray(m.stats) ? m.stats : [];
  const sections = (Array.isArray(m.sections) ? m.sections : []).filter(s => !(s.hideWhenEmpty && !(Array.isArray(s.items) && s.items.length)));
  $('loading').hidden = loaded;
  $('stats').hidden = !loaded || stats.length === 0;
  $('sections').hidden = !loaded || sections.length === 0;
  $('none').hidden = !loaded || sections.length > 0;
  const statsBox = $('stats');
  statsBox.innerHTML = '';
  stats.forEach(s => statsBox.appendChild(statEl(s)));
  const box = $('sections');
  box.className = 'sections' + (Number(m.columns) === 2 ? ' cols-2' : '');
  box.innerHTML = '';
  sections.forEach(s => box.appendChild(sectionEl(s, () => render(current))));
  scroller.scrollTop = keepTop;
}
appsmith.onReady(() => {
  applyTheme(appsmith.theme);
  $('refresh').addEventListener('click', () => appsmith.triggerEvent('onRefresh'));
  render(appsmith.model);
  appsmith.onModelChange(model => render(model));
  if (typeof appsmith.onThemeChange === 'function') appsmith.onThemeChange(applyTheme);
});

