:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --success: #1E7A42;
  --success-bg: #DDF3E4;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
  --mono: Consolas, "Cascadia Mono", "Courier New", monospace;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

.wrap {
  padding: 22px 24px;
  text-align: center;
}

.icon {
  width: 44px;
  height: 44px;
  margin: 0 auto 10px;
  border-radius: 50%;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

h2 {
  margin: 0 0 4px;
  font-size: 18px;
}

.for {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 13px;
  word-break: break-all;
}

.for strong {
  color: var(--text);
}

.pass-box {
  background: var(--surface-alt);
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  padding: 14px 12px;
}

.pass-box code {
  font-family: var(--mono);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--primary);
  user-select: all; /* klik sekali = pilih semua, untuk salin manual */
  word-break: break-all;
}

.note {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.5;
  margin: 14px 0 0;
}

.note strong {
  color: var(--text);
}

.actions {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}

.btn-primary, .btn-secondary {
  height: 38px;
  min-width: 110px;
  padding: 0 18px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover {
  background: var(--surface-alt);
}

.btn-secondary.copied {
  background: var(--success-bg);
  color: var(--success);
  border-color: var(--success-bg);
}

