async function () {
  const hadToken = !!appsmith.store.token;
  try {
    await Auth.load();
  } catch (e) {
    showAlert('Gagal memuat profil: ' + Util.cleanError(e && e.message), 'error');
    return false;
  }
  if (!Auth.me) {
    await removeValue('token');
    if (hadToken) showAlert('Sesi login habis. Silakan login lagi.', 'warning');
    navigateTo('Login');
    return false;
  }
  if (Auth.me.must_change_password) {
    navigateTo('Login', {
      mode: 'ganti'
    });
    return false;
  }
  if (Auth.requiredPerm && !Auth.can(Auth.requiredPerm)) {
    showAlert(`Role ${Auth.me.role_label} tidak punya akses ke halaman ini.`, 'warning');
    navigateTo('Beranda');
    return false;
  }
  for (const q of Auth.pageQueries()) {
    try {
      await q.run();
    } catch (e) {
      showAlert(Util.cleanError(e && e.message), 'error');
    }
  }
  return true;
}

