// cwVariantForm — form varian material di mdlVarian (page Material Detail). Hanya tampilan; simpan lewat
// MaterialDetailCtrl.saveVariant() -> fn_variant_add (banyak sekaligus) / fn_variant_update (satu).
// Tambah: thickness × warna -> baris kombinasi -> Material Code diketik per baris. Kombinasi yang sudah
// terdaftar ditandai dan tidak dikirim. Aturan final (kode unik per pabrik, varian ganda) di DB.
const $ = id => document.getElementById(id);
let lastKey = null;
let busy = false;
let isEdit = false;
let existing = {};      // kunci thickness|warna -> kode yang sudah terdaftar
let rows = [];          // [{ key, thickness, color, code }]

function applyTheme(t) {
  t = t || {};
  const r = document.documentElement.style;
  if (t.primaryColor) r.setProperty('--primary', t.primaryColor);
  if (t.borderRadius) r.setProperty('--radius', t.borderRadius);
  if (t.fontFamily && t.fontFamily !== 'System Default') r.setProperty('--font', `${t.fontFamily}, "Segoe UI", Arial, sans-serif`);
}

function showMessage(m) {
  const box = $('msg');
  if (!m || !m.text) {
    box.hidden = true;
    box.textContent = '';
    return;
  }
  box.className = `msg ${m.type || 'info'}`;
  box.textContent = m.text;
  box.hidden = false;
}

function fillSelect(sel, options, selected) {
  sel.innerHTML = '';
  (options || []).forEach(o => {
    const opt = document.createElement('option');
    opt.value = o.value;
    opt.textContent = o.label;
    sel.appendChild(opt);
  });
  sel.value = selected || '';
}

// "1,20" / "1.2" / 1.2 -> "1.2"; kosong -> ''
function thickKey(v) {
  const s = String(v === null || v === undefined ? '' : v).trim().replace(',', '.');
  return s === '' ? '' : String(Number(s));
}
const thickLabel = k => (k === '' ? 'tanpa thickness' : `${k} mm`);
const colorText = s => String(s || '').trim().replace(/\s+/g, ' ').toUpperCase();
const comboKey = (t, c) => `${t}|${colorText(c).toLowerCase()}`;

// ---- tambah: kombinasi ----
function parseThicknesses() {
  const tokens = $('thicknesses').value.trim().split(/[\s;]+/).filter(x => x);
  const bad = tokens.filter(x => !/^\d+([.,]\d+)?$/.test(x) || Number(x.replace(',', '.')) <= 0);
  if (bad.length) return { error: `Thickness "${bad[0]}" bukan angka mm.` };
  const keys = [...new Set(tokens.map(thickKey))];
  return { list: keys.length ? keys : [''] };
}

function parseColors() {
  const list = $('colors').value.split(/[\n,;]+/).map(colorText).filter(x => x);
  return [...new Set(list)];
}

function combine() {
  showMessage(null);
  const t = parseThicknesses();
  if (t.error) {
    $('thicknesses').classList.add('invalid');
    showMessage({ type: 'error', text: t.error });
    return;
  }
  $('thicknesses').classList.remove('invalid');
  const colors = parseColors();
  $('colors').classList.toggle('invalid', colors.length === 0);
  if (!colors.length) {
    showMessage({ type: 'error', text: 'Isi minimal satu warna.' });
    return;
  }
  const typed = {};
  rows.forEach(r => { typed[r.key] = r.code; });
  rows = [];
  t.list.forEach(th => colors.forEach(c => {
    const key = comboKey(th, c);
    rows.push({ key, thickness: th, color: c, code: typed[key] || '' });
  }));
  drawRows();
  const firstInput = document.querySelector('#comboBody input');
  if (firstInput) firstInput.focus();
}

function drawRows() {
  const body = $('comboBody');
  body.innerHTML = '';
  let fresh = 0;
  rows.forEach((r, i) => {
    const tr = document.createElement('tr');
    const old = existing[r.key];
    const cells = [thickLabel(r.thickness), r.color];
    cells.forEach(text => {
      const td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    const tdCode = document.createElement('td');
    if (old) {
      tdCode.className = 'exists';
      tdCode.textContent = `sudah terdaftar: ${old}`;
      tr.className = 'done';
    } else {
      fresh += 1;
      const inp = document.createElement('input');
      inp.type = 'text';
      inp.maxLength = 40;
      inp.autocomplete = 'off';
      inp.value = r.code;
      inp.placeholder = 'Material Code';
      inp.addEventListener('input', () => { r.code = inp.value; inp.classList.remove('invalid'); });
      inp.addEventListener('keydown', e => {
        if (e.key === 'Enter') {
          const inputs = [...document.querySelectorAll('#comboBody input')];
          const next = inputs[inputs.indexOf(inp) + 1];
          if (next) next.focus(); else submit();
        }
      });
      tdCode.appendChild(inp);
    }
    tr.appendChild(tdCode);
    const tdDel = document.createElement('td');
    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'x';
    del.title = 'Hapus baris';
    del.textContent = '✕';
    del.addEventListener('click', () => { rows.splice(i, 1); drawRows(); });
    tdDel.appendChild(del);
    tr.appendChild(tdDel);
    body.appendChild(tr);
  });
  $('comboWrap').hidden = rows.length === 0;
  const skipped = rows.length - fresh;
  $('comboInfo').textContent = rows.length
    ? `${fresh} varian baru` + (skipped ? ` · ${skipped} sudah terdaftar (dilewati)` : '')
    : '';
}

// Isi ulang field hanya saat modal dibuka (key berubah) — busy/message tidak menghapus ketikan user
function fillForm(m) {
  const f = m.form || {};
  isEdit = m.mode === 'edit';
  existing = {};
  (m.existing || []).forEach(v => { existing[comboKey(thickKey(v.thickness_mm), v.color)] = v.code; });
  $('title').textContent = isEdit ? 'Ubah Varian' : 'Tambah Varian';
  $('materialLabel').textContent = m.materialLabel || '';
  $('addBox').hidden = isEdit;
  $('editBox').hidden = !isEdit;
  ['thicknesses', 'colors', 'thickness', 'color', 'code'].forEach(id => $(id).classList.remove('invalid'));
  if (isEdit) {
    $('thickness').value = thickKey(f.thickness_mm);
    $('color').value = f.color || '';
    $('code').value = f.code || '';
    fillSelect($('status'), m.statusOptions, f.status || 'ACTIVE');
    $('code').focus();
  } else {
    $('thicknesses').value = '';
    $('colors').value = '';
    rows = [];
    drawRows();
    $('thicknesses').focus();
  }
}

function setBusy(v) {
  busy = v;
  $('btnSave').disabled = v;
  $('btnCancel').disabled = v;
  $('btnX').disabled = v;
  $('btnCombine').disabled = v;
  $('btnSave').textContent = v ? 'Menyimpan…' : 'Simpan';
}

function render(model) {
  const m = model || {};
  if (m.key !== lastKey) {
    lastKey = m.key;
    fillForm(m);
  }
  showMessage(m.message);
  setBusy(!!m.busy);
}

function submitEdit() {
  const th = $('thickness').value.trim();
  const color = colorText($('color').value);
  const code = $('code').value.trim().replace(/\s+/g, ' ').toUpperCase();
  ['thickness', 'color', 'code'].forEach(id => $(id).classList.remove('invalid'));
  if (th && (!/^\d+([.,]\d+)?$/.test(th) || Number(th.replace(',', '.')) <= 0)) {
    $('thickness').classList.add('invalid');
    showMessage({ type: 'error', text: 'Thickness harus angka mm (kosongkan bila tidak ada).' });
    return;
  }
  if (!color || !code) {
    $(color ? 'code' : 'color').classList.add('invalid');
    showMessage({ type: 'error', text: 'Warna dan Material Code wajib diisi.' });
    return;
  }
  appsmith.updateModel({ thickness_mm: thickKey(th), color, code, status: $('status').value });
  appsmith.triggerEvent('onSave');
}

function submitAdd() {
  const fresh = rows.filter(r => !existing[r.key]);
  if (!fresh.length) {
    showMessage({ type: 'error', text: rows.length ? 'Semua kombinasi sudah terdaftar.' : 'Klik "Buat kombinasi" dulu.' });
    return;
  }
  const inputs = [...document.querySelectorAll('#comboBody input')];
  const empty = inputs.find(i => !i.value.trim());
  if (empty) {
    empty.classList.add('invalid');
    empty.focus();
    showMessage({ type: 'error', text: 'Isi Material Code di setiap baris (atau hapus barisnya).' });
    return;
  }
  const codes = fresh.map(r => r.code.trim().replace(/\s+/g, ' ').toUpperCase());
  const dup = codes.find((c, i) => codes.indexOf(c) !== i);
  if (dup) {
    showMessage({ type: 'error', text: `Material Code ${dup} dipakai di lebih dari satu baris.` });
    return;
  }
  appsmith.updateModel({
    items: fresh.map((r, i) => ({ thickness_mm: r.thickness, color: r.color, code: codes[i] })),
  });
  appsmith.triggerEvent('onSave');
}

function submit() {
  if (busy) return;
  if (isEdit) submitEdit(); else submitAdd();
}

function cancel() {
  if (!busy) appsmith.triggerEvent('onCancel');
}

appsmith.onReady(() => {
  $('btnSave').addEventListener('click', submit);
  $('btnCancel').addEventListener('click', cancel);
  $('btnX').addEventListener('click', cancel);
  $('btnCombine').addEventListener('click', combine);
  $('thicknesses').addEventListener('keydown', e => {
    if (e.key === 'Enter') combine();
  });
  ['thickness', 'color', 'code'].forEach(id => $(id).addEventListener('keydown', e => {
    if (e.key === 'Enter') submit();
  }));
  applyTheme(appsmith.theme);
  render(appsmith.model);
  appsmith.onModelChange(render);
  if (typeof appsmith.onThemeChange === 'function') appsmith.onThemeChange(applyTheme);
});

