  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --info-bg: #DCE4F3;
  --warn: #B45309;
  --warn-bg: #FEF3C7;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 13px;
  overflow: hidden;
}

[hidden] {
  display: none !important;
}

.wrap {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 8px;
  min-height: 36px;
}

.msg {
  flex: 1;
  border-radius: var(--radius);
  padding: 6px 10px;
  font-size: 12.5px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.info, .msg.success {
  background: var(--info-bg);
  color: var(--primary);
}

.status {
  margin-left: auto;
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.scroll {
  flex: 1;
  overflow: auto;
  border-top: 1px solid var(--border);
}

.grid {
  border-collapse: separate;
  border-spacing: 0;
  width: max-content;
  min-width: 100%;
  table-layout: fixed;
}

.grid th, .grid td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4px 6px;
  vertical-align: top;
  background: var(--surface);
  overflow: hidden;
  text-overflow: ellipsis;
}

.grid thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--head);
  font-size: 12px;
  font-weight: 700;
  text-align: left;
  white-space: nowrap;
  padding: 6px;
}

.grid .c-no {
  position: sticky;
  left: 0;
  z-index: 1;
  width: 64px;
  min-width: 64px;
  max-width: 64px;
}

.grid .c-comp {
  position: sticky;
  left: 64px;
  z-index: 1;
  width: 190px;
  min-width: 190px;
  max-width: 190px;
  box-shadow: 2px 0 0 var(--border);
}

.grid thead .c-no, .grid thead .c-comp {
  z-index: 3;
}

.c-mat {
  width: 270px;
  min-width: 270px;
}

.c-sup {
  width: 190px;
  min-width: 190px;
}

.c-uom {
  width: 64px;
  min-width: 64px;
  color: var(--muted);
}

.c-thk {
  width: 80px;
  min-width: 80px;
  color: var(--muted);
}

.c-rem {
  width: 200px;
  min-width: 200px;
}

.c-act {
  width: 84px;
  min-width: 84px;
}

.c-art {
  width: 190px;
  min-width: 190px;
}

.art-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 4px;
}

.art-code {
  display: block;
}

.art-cw {
  display: block;
  font-weight: 400;
  color: var(--muted);
  font-size: 11.5px;
  white-space: normal;
}

.drop {
  flex: none;
  border: none;
  background: none;
  color: var(--muted);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  padding: 0 4px;
  border-radius: 4px;
}

.drop:hover {
  color: var(--danger);
  background: var(--danger-bg);
}

.drop.confirm {
  color: #fff;
  background: var(--danger);
  font-weight: 700;
}

tr.sub td {
  background: #FAFBFD;
}

tr.sub .c-comp .name::before {
  content: "↳ ";
  color: var(--muted);
}

.local {
  display: inline-block;
  margin-left: 4px;
  font-size: 10.5px;
  color: var(--muted);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0 4px;
}

input.cell, textarea.cell {
  display: block;
  width: 100%;
  height: 28px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 4px;
  font: inherit;
  color: inherit;
  background: transparent;
}

input.cell:hover, textarea.cell:hover {
  border-color: var(--border);
}

input.cell:focus, textarea.cell:focus {
  outline: none;
  border-color: var(--accent);
  background: #fff;
  box-shadow: 0 0 0 2px rgba(59, 111, 224, 0.18);
}

input.cell.invalid, textarea.cell.invalid {
  border-color: var(--danger);
}

input.cell:disabled, textarea.cell:disabled {
  background: var(--surface-alt);
  cursor: not-allowed;
}

.ro {
  display: block;
  padding: 5px 0;
  white-space: normal;
  word-break: break-word;
}

.ro.none {
  color: var(--muted);
}

.badge {
  display: inline-block;
  margin-top: 2px;
  font-size: 10.5px;
  font-weight: 600;
  border-radius: 4px;
  padding: 0 5px;
}

.badge.proposed {
  background: var(--warn-bg);
  color: var(--warn);
}

.badge.inactive {
  background: var(--danger-bg);
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-weight: 600;
  padding: 5px 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.link.muted {
  color: var(--muted);
}

.c-act .link {
  display: block;
}

.link.danger {
  color: var(--danger);
  font-weight: 400;
  font-size: 12px;
}

.link.danger.confirm {
  color: #fff;
  background: var(--danger);
  border-radius: 4px;
  padding: 2px 6px;
  font-weight: 700;
}

.btn {
  height: 28px;
  padding: 0 10px;
  border-radius: 4px;
  border: 1px solid var(--primary);
  background: var(--primary);
  color: #fff;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.6;
  cursor: default;
}

tr.add td, tr.subform td {
  background: #F7F9FC;
}

tr.add input.cell, tr.subform input.cell {
  border-color: var(--border);
  background: #fff;
}

.hint {
  display: block;
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
  white-space: normal;
}

.empty {
  color: var(--muted);
  padding: 16px 8px;
}

/* F10b: kotak teks warna & Remarks membungkus teks */
textarea.cell {
  min-height: 28px;
  padding: 5px 6px;
  line-height: 1.35;
  resize: none;
  overflow: hidden;
  white-space: pre-wrap;
  word-break: break-word;
}

.ro.lines {
  white-space: pre-line;
}

.suggest {
  position: fixed;
  z-index: 50;
  max-width: 320px;
  max-height: 240px;
  overflow-y: auto;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  box-shadow: 0 8px 20px rgba(18, 42, 82, 0.16);
  padding: 4px 0;
  font-size: 12.5px;
}

.suggest .opt {
  padding: 5px 10px;
  cursor: pointer;
  white-space: normal;
}

.suggest .opt:hover, .suggest .opt.on {
  background: var(--surface-alt, #EEF1F7);
  color: var(--primary);
}

