:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --info-bg: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], input[type=date], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  background: #fff;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

input:disabled, select:disabled {
  background: var(--surface-alt);
  color: var(--muted);
  cursor: not-allowed;
}

input.invalid, select.invalid {
  border-color: var(--danger);
}

.switch-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
}

.switch-row input:focus-visible + .switch {
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.25);
}

.field-note {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.info {
  background: var(--info-bg);
  color: var(--primary);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 4px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 22px;
}

.btn-primary, .btn-secondary {
  height: 38px;
  padding: 0 18px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

textarea {
  width: 100%;
  min-height: 96px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  resize: vertical;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

textarea.invalid {
  border-color: var(--danger);
}

.summary {
  background: var(--surface-alt);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-top: 4px;
  white-space: pre-line;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.checklist {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.checklist li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
}

.checklist .icon {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
}

.checklist li.ok .icon {
  background: #16A34A;
}

.checklist li.fail {
  background: var(--danger-bg);
}

.checklist li.fail .icon {
  background: var(--danger);
}

.checklist li.warn {
  background: #FEF3C7;
}

.checklist li.warn .icon {
  background: #D97706;
}

.checklist .detail {
  color: var(--muted);
  font-size: 12.5px;
  margin-top: 2px;
}

.blocked {
  background: var(--danger-bg);
  color: var(--danger);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  font-weight: 600;
  margin-top: 12px;
}

/* F10b: gambar di change log */
.opt-label {
  font-weight: 400;
  color: var(--muted);
}

.paste {
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  padding: 12px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  background: #FAFBFD;
  outline: none;
}

.paste:focus, .paste.over {
  border-color: var(--accent);
  background: #F2F6FE;
}

.thumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}

.thumb {
  position: relative;
  width: 96px;
  height: 72px;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
  background: #fff;
}

.thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.thumb button {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 20px;
  height: 20px;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
  font-size: 11px;
  line-height: 20px;
  cursor: pointer;
  padding: 0;
}

