  $('vprev').disabled = n === 0;
  $('vnext').disabled = n === list.length - 1;
  $('viewer').hidden = false;
}
function closeViewer() {
  current = -1;
  $('viewer').hidden = true;
  $('vimg').removeAttribute('src');
}
