.badge.proposed {
  background: var(--warn-bg);
  color: var(--warn);
}

.badge.inactive {
  background: var(--danger-bg);
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-weight: 600;
  padding: 5px 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.link.muted {
  color: var(--muted);
}

.c-act .link {
  display: block;
}

.link.danger {
  color: var(--danger);
  font-weight: 400;
  font-size: 12px;
}

.link.danger.confirm {
  color: #fff;
  background: var(--danger);
  border-radius: 4px;
  padding: 2px 6px;
  font-weight: 700;
}

.btn {
  height: 28px;
  padding: 0 10px;
  border-radius: 4px;
  border: 1px solid var(--primary);
  background: var(--primary);
  color: #fff;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.6;
  cursor: default;
}

tr.add td, tr.subform td {
  background: #F7F9FC;
}

tr.add input.cell, tr.subform input.cell {
  border-color: var(--border);
  background: #fff;
}

.hint {
  display: block;
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
  white-space: normal;
}

.empty {
  color: var(--muted);
  padding: 16px 8px;
}

/* F10b: kotak teks warna & Remarks membungkus teks */
textarea.cell {
  min-height: 28px;
  padding: 5px 6px;
  line-height: 1.35;
  resize: none;
  overflow: hidden;
  white-space: pre-wrap;
  word-break: break-word;
}

.ro.lines {
  white-space: pre-line;
}

.suggest {
  position: fixed;
  z-index: 50;
  max-width: 320px;
  max-height: 240px;
  overflow-y: auto;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  box-shadow: 0 8px 20px rgba(18, 42, 82, 0.16);
  padding: 4px 0;
  font-size: 12.5px;
}

.suggest .opt {
  padding: 5px 10px;
  cursor: pointer;
  white-space: normal;
}

.suggest .opt:hover, .suggest .opt.on {
  background: var(--surface-alt, #EEF1F7);
  color: var(--primary);
}

