  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(59, 111, 224, 0.18);
}

input.cell.invalid {
  border-color: var(--danger);
  background: var(--danger-bg);
}

input.cell.need {
  border-color: var(--warn);
  background: var(--warn-bg);
}

.badge {
  display: inline-block;
  margin-top: 2px;
  font-size: 10.5px;
  font-weight: 600;
  border-radius: 4px;
  padding: 0 5px;
}

.badge.master { background: var(--info-bg); color: var(--primary); }
.badge.override, .badge.quotation { background: var(--warn-bg); color: var(--warn); }
.hint {
  display: block;
  font-size: 11px;
  color: var(--muted);
  white-space: normal;
  text-align: right;
}

.hint.warn {
  color: var(--warn);
}

.empty {
  color: var(--muted);
  padding: 16px 8px;
}

/* ---------------------------------------------------------------- F8: harga, banner, rekap */
.acts {
  margin-top: 2px;
  text-align: right;
}

.lnk {
  border: none;
  background: none;
  padding: 0;
  font: inherit;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--accent);
  cursor: pointer;
}

.lnk:hover:not(:disabled) {
  text-decoration: underline;
}

.lnk.danger {
  color: var(--danger);
}

.lnk:disabled, .bbtn:disabled {
  opacity: 0.5;
  cursor: default;
}

.banners {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 8px 6px;
}

.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: var(--radius);
  padding: 6px 10px;
  font-size: 12.5px;
}

.banner.danger { background: var(--danger-bg); color: var(--danger); }
.banner.warn { background: var(--warn-bg); color: var(--warn); }
.banner.info { background: var(--info-bg); color: var(--primary); }

.banner .btext {
  flex: 1;
}

.bbtn {
  flex: none;
  height: 28px;
  padding: 0 12px;
  border: none;
  border-radius: var(--radius);
  background: var(--primary);
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.recap {
  flex: none;
  display: grid;
  grid-template-columns: repeat(9, minmax(110px, 1fr));
  gap: 8px;
  padding: 8px;
  border-top: 1px solid var(--border);
  background: var(--surface-alt);
}

.rf label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  margin-bottom: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rf .rv {
  height: 28px;
  line-height: 28px;
  text-align: right;
  white-space: nowrap;
}

.rf.strong .rv {
  font-weight: 700;
  color: var(--primary);
}

.vl {
  display: inline-block;
  margin-left: 6px;
  font-size: 10.5px;
  font-weight: 700;
  line-height: 16px;
  border-radius: 4px;
  padding: 0 5px;
}

.vl.over { background: var(--danger-bg); color: var(--danger); }
.vl.under { background: #E3F4EA; color: #1E7B45; }
.vl.sesuai { background: var(--info-bg); color: var(--primary); }

/* ---------------------------------------------------------------- F8b: subtotal, tabel bawah */
tr.subtotal td {
  background: #F7F9FC;
  font-weight: 700;
  color: var(--primary);
  border-bottom: 2px solid var(--border);
}

tr.subtotal .glabel {
  position: sticky;
  left: 6px;
}

.recap {
  grid-template-columns: repeat(5, minmax(130px, 220px));
}

.below {
  position: sticky;
  left: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 16px;
  padding: 14px 8px 18px;
  max-width: 100%;
}

.sect h3 {
  margin: 0 0 6px;
  font-size: 13px;
  color: var(--primary);
}

table.mini {
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

table.mini th, table.mini td {
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
  white-space: nowrap;
}

table.mini th {
  background: var(--head);
  font-size: 12px;
  text-align: left;
}

table.mini .n {
  text-align: right;
  width: 150px;
}

table.mini .lbl {
  font-weight: 600;
}

table.mini .muted, .note {
  color: var(--muted);
  font-size: 11.5px;
}

table.mini .act {
  width: 70px;
  text-align: right;
}

table.cost td:nth-child(3) { width: 220px; }
table.cost td:nth-child(5) { width: 200px; }

table.cost tr.auto td {
  background: #FAFBFD;
}

table.cost tr.total td {
  background: var(--surface-alt);
  font-weight: 700;
  color: var(--primary);
}

table.cost tr.add td {
  background: #FCFDFE;
}

input.cell.txt {
  text-align: left;
}

select.cell.sel {
  width: 100%;
  height: 28px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font: inherit;
  background: #fff;
}

select.cell.sel.invalid {
  border-color: var(--danger);
}

.note {
  margin-top: 6px;
  max-width: 320px;
  white-space: normal;
}

