:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --info-bg: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], input[type=date], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  background: #fff;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

input:disabled, select:disabled {
  background: var(--surface-alt);
  color: var(--muted);
  cursor: not-allowed;
}

input.invalid, select.invalid {
  border-color: var(--danger);
}

.switch-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
}

.switch-row input:focus-visible + .switch {
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.25);
}

.field-note {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.info {
  background: var(--info-bg);
  color: var(--primary);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 4px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 22px;
}

.btn-primary, .btn-secondary {
  height: 38px;
  padding: 0 18px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

textarea {
  width: 100%;
  min-height: 96px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  resize: vertical;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

textarea.invalid {
  border-color: var(--danger);
}

.summary {
  background: var(--surface-alt);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-top: 4px;
  white-space: pre-line;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.checklist {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.checklist li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
}

.checklist .icon {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
}

.checklist li.ok .icon {
  background: #16A34A;
}

.checklist li.fail {
  background: var(--danger-bg);
}

.checklist li.fail .icon {
  background: var(--danger);
}

.checklist li.warn {
  background: #FEF3C7;
}

.checklist li.warn .icon {
  background: #D97706;
}

.checklist .detail {
  color: var(--muted);
  font-size: 12.5px;
  margin-top: 2px;
}

.blocked {
  background: var(--danger-bg);
  color: var(--danger);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  font-weight: 600;
  margin-top: 12px;
}

/* F10b: gambar di change log */
.opt-label {
  font-weight: 400;
  color: var(--muted);
}

.paste {
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  padding: 12px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  background: #FAFBFD;
  outline: none;
}

.paste:focus, .paste.over {
  border-color: var(--accent);
  background: #F2F6FE;
}

.thumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}

.thumb {
  position: relative;
  width: 96px;
  height: 72px;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
  background: #fff;
}

.thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.thumb button {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 20px;
  height: 20px;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
  font-size: 11px;
  line-height: 20px;
  cursor: pointer;
  padding: 0;
}

srcDoc.js:
// cwPublishForm — modal Terbitkan revisi: Specsheet (mdlTerbit, F6) dan CBD (mdlCbdTerbit, F8). Hanya tampilan;
// checklist dihitung di DB (v_revision_checklist / v_cbd_checklist) dan disusun <Page>Ctrl.publishFormModel().
// Terbit lewat SpecCtrl.publish() / CbdCtrl.publish() (checklist, kategori, dan alasan dicek lagi di DB).
// F10b: gambar opsional (tempel Ctrl+V / pilih file; PNG/JPG ≤ 5 MB, maks. model.maxImages) -> model.images
//   [{ name, data (base64 tanpa awalan) }]; dilampirkan ke change log oleh <Page>Ctrl setelah terbit.
const $ = id => document.getElementById(id);
let lastKey = null;
let busy = false;
let blocked = false;
let requiresReason = true;
let images = []; // { name, type, size, data, url }
let maxImages = 5;
const MAX_BYTES = 5 * 1024 * 1024;
function applyTheme(t) {
  t = t || {};
  const r = document.documentElement.style;
  if (t.primaryColor) r.setProperty('--primary', t.primaryColor);
  if (t.borderRadius) r.setProperty('--radius', t.borderRadius);
  if (t.fontFamily && t.fontFamily !== 'System Default') r.setProperty('--font', `${t.fontFamily}, "Segoe UI", Arial, sans-serif`);
}
function showMessage(m) {
  const box = $('msg');
  if (!m || !m.text) {
    box.hidden = true;
    box.textContent = '';
    return;
  }
  box.className = `msg ${m.type || 'info'}`;
  box.textContent = m.text;
  box.hidden = false;
}
function renderChecks(m) {
  const list = $('checks');
  list.innerHTML = '';
  const checks = m.checks || [];
  checks.forEach(c => {
    const li = document.createElement('li');
    li.className = c.ok ? 'ok' : c.blocking ? 'fail' : 'warn';
    li.innerHTML = '<span class="icon" aria-hidden="true"></span><div><strong></strong><div class="detail"></div></div>';
    li.querySelector('.icon').textContent = c.ok ? '✓' : c.blocking ? '✕' : '!';
    li.querySelector('strong').textContent = c.label;
    li.querySelector('.detail').textContent = c.detail || '';
    li.querySelector('.detail').hidden = !c.detail;
    list.appendChild(li);
  });
  const failed = checks.filter(c => c.blocking && !c.ok).length;
  blocked = !!m.blocked || failed > 0 || !checks.length;
  $('blocked').textContent = !checks.length ? 'Checklist belum termuat. Tutup lalu buka lagi.' : `Perbaiki ${failed} hal di atas ${m.blockedWhere || 'di grid BOM'} sebelum terbit.`;
  $('blocked').hidden = !blocked;
  $('formBox').hidden = blocked;
  $('btnSave').hidden = blocked;
}

// Isi ulang hanya saat modal dibuka (key berubah) — busy/message tidak menghapus isian user
function fillForm(m) {
  $('title').textContent = m.title || 'Terbitkan Revisi';
  const sel = $('category');
  sel.innerHTML = '<option value="">— pilih kategori —</option>';
  (m.categories || []).forEach(c => {
    const opt = document.createElement('option');
    opt.value = c.value;
    opt.textContent = c.label;
    sel.appendChild(opt);
  });
  sel.value = m.defaultCategory || '';
  sel.classList.remove('invalid');
  requiresReason = m.requiresReason !== false;
  $('reasonReq').hidden = !requiresReason;
  $('reason').value = '';
  $('reason').classList.remove('invalid');
  $('reason').placeholder = requiresReason ? 'Apa yang berubah dibanding revisi sebelumnya?' : 'Kosongkan = "Revisi awal."';
  $('reasonHint').textContent = requiresReason ? '' : 'Opsional untuk revisi awal.';
  $('reasonHint').hidden = requiresReason;
  maxImages = Number(m.maxImages) || 5;
  images = [];
  renderImages();
}

// ---------------------------------------------------------------- gambar
function renderImages() {
  const box = $('thumbs');
  box.innerHTML = '';
  images.forEach((img, n) => {
    const t = document.createElement('div');
    t.className = 'thumb';
    t.title = `${img.name} (${Math.ceil(img.size / 1024)} KB)`;
    const pic = document.createElement('img');
    pic.src = img.url;
    pic.alt = img.name;
    const x = document.createElement('button');
    x.type = 'button';
    x.textContent = '✕';
    x.title = 'Hapus gambar ini';
    x.addEventListener('click', () => {
      images.splice(n, 1);
      renderImages();
    });
    t.appendChild(pic);
    t.appendChild(x);
    box.appendChild(t);
  });
  $('imgHint').textContent = `PNG / JPG, maks. 5 MB per gambar, maks. ${maxImages} gambar` + (images.length ? ` · ${images.length} dipilih` : '') + '.';
}
function addFiles(files) {
  const list = Array.from(files || []).filter(f => f && f.type && f.type.indexOf('image/') === 0);
  if (!list.length) return false;
  let error = '';
  list.forEach(f => {
    if (images.length >= maxImages) {
      error = `Maksimal ${maxImages} gambar.`;
      return;
    }
    if (f.type !== 'image/png' && f.type !== 'image/jpeg') {
      error = 'Hanya gambar PNG atau JPG.';
      return;
    }
    if (f.size > MAX_BYTES) {
      error = `${f.name || 'Gambar'} lebih dari 5 MB.`;
      return;
    }
    const slot = {
      name: '',
      type: f.type,
      size: f.size,
      data: '',
      url: ''
    };
    const ext = f.type === 'image/png' ? 'png' : 'jpg';
    slot.name = f.name && f.name !== 'image.png' ? f.name : `gambar-${images.length + 1}.${ext}`;
    images.push(slot);
    const reader = new FileReader();
    reader.onload = () => {
      slot.url = String(reader.result || '');
      slot.data = slot.url.replace(/^data:[^,]*,/, '');
      renderImages();
    };
    reader.readAsDataURL(f);
  });
  renderImages();
  showMessage(error ? {
    type: 'error',
    text: error
  } : null);
  return true;
}
function setBusy(v) {
  busy = v;
  $('btnSave').disabled = v;
  $('btnCancel').disabled = v;
  $('btnX').disabled = v;
  $('btnSave').textContent = v ? 'Menerbitkan…' : 'Terbitkan';
}
function render(model) {
  const m = model || {};
  if (m.key !== lastKey) {
    lastKey = m.key;
    fillForm(m);
  }
  renderChecks(m);
  showMessage(m.message);
  setBusy(!!m.busy);
}
function submit() {
  if (busy || blocked) return;
  const category = $('category').value;
  const reason = $('reason').value.trim();
  if (!category) {
    $('category').classList.add('invalid');
    $('category').focus();
    showMessage({
      type: 'error',
      text: 'Pilih kategori perubahan.'
    });
    return;
  }
  if (requiresReason && !reason) {
    $('reason').classList.add('invalid');
    $('reason').focus();
    showMessage({
      type: 'error',
      text: 'Alasan perubahan wajib diisi untuk revisi ini.'
    });
    return;
  }
  if (images.some(i => !i.data)) {
    showMessage({
      type: 'error',
      text: 'Gambar masih dimuat, coba lagi sebentar.'
    });
    return;
  }
  showMessage(null);
  appsmith.updateModel({
    category,
    reason,
    images: images.map(i => ({
      name: i.name,
      data: i.data
    }))
  });
  appsmith.triggerEvent('onPublish');
}
function cancel() {
  if (!busy) appsmith.triggerEvent('onCancel');
}
appsmith.onReady(() => {
  $('btnSave').addEventListener('click', submit);
  $('btnCancel').addEventListener('click', cancel);
  $('btnX').addEventListener('click', cancel);
  $('category').addEventListener('change', () => $('category').classList.remove('invalid'));
  $('reason').addEventListener('input', () => $('reason').classList.remove('invalid'));
  // Tempel gambar di mana pun di form (teks biasa tetap tertempel normal)
  document.addEventListener('paste', e => {
    if (busy || blocked) return;
    const files = Array.from(e.clipboardData && e.clipboardData.items || []).filter(it => it.kind === 'file').map(it => it.getAsFile());
    if (files.length && addFiles(files)) e.preventDefault();
  });
  $('btnPick').addEventListener('click', () => $('file').click());
  $('file').addEventListener('change', () => {
    addFiles($('file').files);
    $('file').value = '';
  });
  const drop = $('paste');
  drop.addEventListener('dragover', e => {
    e.preventDefault();
    drop.classList.add('over');
  });
  drop.addEventListener('dragleave', () => drop.classList.remove('over'));
  drop.addEventListener('drop', e => {
    e.preventDefault();
    drop.classList.remove('over');
    addFiles(e.dataTransfer && e.dataTransfer.files);
  });
  applyTheme(appsmith.theme);
  render(appsmith.model);
  appsmith.onModelChange(render);
  if (typeof appsmith.onThemeChange === 'function') appsmith.onThemeChange(applyTheme);
});

