}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 13px;
  overflow: hidden;
}

[hidden] {
  display: none !important;
