}

.step.current {
  box-shadow: inset 0 -3px 0 var(--primary);
}

.stage {
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.step.has-revs .stage {
  color: var(--primary);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 26px;
