  background: var(--primary);
  color: #fff;
  border-style: solid;
  border-color: var(--primary);
}

.chip.draft.active {
  background: var(--draft);
  border-color: var(--draft);
}

.chip:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.3);
}

.empty {
  color: var(--muted);
  padding: 0 4px;
}

.chip.needs {
  border-color: var(--danger);
  color: var(--danger);
}

.chip.needs.active {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.arts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
