async function () {
		// Baca model dulu — model di-reset saat state (Default model) berubah
		const m = cwSupplierForm.model || {};
		const data = {
			id: SupplierCtrl.form.id,
			name: String(m.name || '').trim(),
			status: SupplierCtrl.isNew ? 'ACTIVE' : m.status,
		};
		if (!data.name) {
			SupplierCtrl.message = { type: 'error', text: 'Nama supplier wajib diisi.' };
			return;
		}
		SupplierCtrl.message = null;
		SupplierCtrl.busy = true;
		try {
			await (SupplierCtrl.isNew ? a_supplier_insert : a_supplier_update).run(data);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlSupplier');
				await removeValue('token');
				showAlert('Sesi login habis. Silakan login lagi.', 'warning');
				navigateTo('Login');
				return;
			}
			SupplierCtrl.message = { type: 'error', text: Util.cleanError(msg) };   // mis. "Supplier "X" sudah ada."
			return;
		} finally {
			SupplierCtrl.busy = false;
		}
		closeModal('mdlSupplier');
		showAlert(SupplierCtrl.isNew ? 'Supplier ditambahkan.' : 'Supplier disimpan.', 'success');
		try { await q_suppliers.run(); } catch (e) { /* abaikan */ }
	}

