async function () {
		// Baca model dulu — model di-reset saat state (Default model) berubah
		const m = cwKomponenForm.model || {};
		const data = {
			id: KomponenCtrl.form.id,
			group_code: m.group_code,
			number: Number(m.number),
			name: String(m.name || '').trim(),
			status: KomponenCtrl.isNew ? 'ACTIVE' : m.status,
		};
		if (!data.group_code || !data.name || !Number.isInteger(data.number)) {
			KomponenCtrl.message = { type: 'error', text: 'Lengkapi kelompok, nomor, dan nama komponen.' };
			return;
		}
		KomponenCtrl.message = null;
		KomponenCtrl.busy = true;
		try {
			await (KomponenCtrl.isNew ? a_component_add : a_component_update).run(data);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlKomponen');
				await removeValue('token');
				showAlert('Sesi login habis. Silakan login lagi.', 'warning');
				navigateTo('Login');
				return;
			}
			KomponenCtrl.message = { type: 'error', text: Util.cleanError(msg) };   // aturan nomor / pemakaian dari DB
			return;
		} finally {
			KomponenCtrl.busy = false;
		}
		closeModal('mdlKomponen');
		showAlert(KomponenCtrl.isNew ? 'Komponen ditambahkan.' : 'Komponen disimpan.', 'success');
		for (const q of [q_components, q_component_groups]) {
			try { await q.run(); } catch (e) { /* abaikan */ }
		}
	}

