actionConfiguration.body:
async function () {
		const f = cwPriceForm.model || {};
		const params = {
			link_id: f.link_id, color: f.color, price: f.price, currency: f.currency,
			valid_from: f.valid_from, reference: f.reference,
		};
		if (!params.link_id || !params.price || !params.currency || !params.valid_from) {
			MaterialDetailCtrl.priceMsg = { type: 'error', text: 'Lengkapi supplier, harga, currency, dan tanggal berlaku.' };
			return;
		}
		const ok = await MaterialDetailCtrl.runForm(a_price_add, params,
			v => { MaterialDetailCtrl.priceMsg = v; }, v => { MaterialDetailCtrl.priceBusy = v; }, 'mdlHarga');
		if (!ok) return;
		closeModal('mdlHarga');
		showAlert('Usulan harga terkirim, menunggu approval Manager Costing.', 'success');
		await MaterialDetailCtrl.refresh([q_prices, q_material]);
	}

