actionConfiguration.body:
async function () {
  const m = cwModelForm.model || ({});
  const data = {
    code: m.code,
    name: m.name,
    category: m.category,
    factory: m.factory,
    outsole_mold: m.outsole_mold,
    last_no: m.last_no,
    construction: m.construction,
    size_range: m.size_range,
    sample_size: m.sample_size
  };
  if (!data.code || !data.name) {
    ModelCtrl.message = {
      type: 'error',
      text: 'Kode dan nama model wajib diisi.'
    };
    return;
  }
  ModelCtrl.message = null;
  ModelCtrl.busy = true;
  try {
    await a_model_add.run(data);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlModel');
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    ModelCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    ModelCtrl.busy = false;
  }
  closeModal('mdlModel');
  const id = a_model_add.data && a_model_add.data[0] && a_model_add.data[0].id;
  showAlert(`Model ${data.code} ditambahkan. Tambahkan season & article-nya.`, 'success');
  if (id) navigateTo('Model Detail', {
    id
  });
}

