function (msg) {
  const text = String(msg || 'Terjadi kesalahan.');
  const m = text.match(/constraint "([^"]+)"/);
  if (m && Util.errorMessages[m[1]]) return Util.errorMessages[m[1]];
  return text.replace(/^[\s\S]*?ERROR:\s*/, '').replace(/^SESI_HABIS:\s*/, '').replace(/\s*(Where|Detail|Hint|CONTEXT|Position):[\s\S]*$/, '').trim();
}

