async function () {
  const f = cwSeasonForm.model || ({});
  const ok = await ModelDetailCtrl.runForm(a_season_add, {
    model_id: appsmith.URL.queryParams.id,
    season: f.season
  }, v => {
    ModelDetailCtrl.seasonMsg = v;
  }, v => {
    ModelDetailCtrl.seasonBusy = v;
  }, 'mdlSeason');
  if (!ok) return;
  closeModal('mdlSeason');
  const id = a_season_add.data && a_season_add.data[0] && a_season_add.data[0].id;
  showAlert(`Season ${f.season} ditambahkan.`, 'success');
  await ModelDetailCtrl.refresh([q_seasons]);
  await ModelDetailCtrl.pickSeason(id || ModelDetailCtrl.seasonId);
}

