actionConfiguration.body:
async function () {
  const a = (cwBomGrid.model || ({})).action;
  if (!a || !a.type) return;
  const r = SpecCtrl.revision();
  if (!r) return;
  const actions = {
    addLine: [a_bom_add_line, {
      revision_id: r.id,
      component_id: a.component_id,
      local_no: a.local_no,
      local_name: a.local_name,
      material_id: a.material_id,
      supplier_id: a.supplier_id,
      process: a.process
    }, ['options', 'colors']],
    addSub: [a_bom_add_sub, {
      parent_id: a.parent_id,
      sub_name: a.sub_name,
      material_id: a.material_id,
      supplier_id: a.supplier_id,
      process: a.process
    }, ['options']],
    replaceMaterial: [a_bom_replace_material, {
      line_id: a.line_id,
      material_id: a.material_id
    }, ['options']],
    setSupplier: [a_bom_set_supplier, {
      line_id: a.line_id,
      supplier_id: a.supplier_id
    }, ['options']],
    setProcess: [a_bom_set_process, {
      line_id: a.line_id,
      process: a.process
    }, []],
    setCell: [a_cell_save, {
      line_id: a.line_id,
      article_id: a.article_id,
      color: a.color
    }, ['colors']],
    dropArticle: [a_rev_article_set, {
      revision_id: r.id,
      article_id: a.article_id,
      status: 'DROPPED'
    }, ['articles']],
    deleteLine: [a_bom_delete_line, {
      line_id: a.line_id
    }, ['colors']]
  };
  const def = actions[a.type];
  if (!def) return;
  BomCtrl.busyCount = BomCtrl.busyCount + 1;
  try {
    await def[0].run(def[1]);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    BomCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    await BomCtrl.reload([]);
    return;
  } finally {
    BomCtrl.busyCount = Math.max(0, BomCtrl.busyCount - 1);
  }
  BomCtrl.message = null;
  if (a.type === 'addLine' || a.type === 'addSub') BomCtrl.okKey = BomCtrl.okKey + 1;
  await BomCtrl.reload(def[2]);
}

