function () {
  const r = SpecCtrl.revision();
  if (!r) return '';
  const dropped = BomCtrl.articles().filter(a => a.rev_status === 'DROPPED').map(a => a.code);
  const notIn = BomCtrl.articles().filter(a => !a.rev_status).map(a => a.code);
  const parts = [`${BomCtrl.activeArticles().length} article aktif`];
  if (dropped.length) parts.push(`di-drop: ${dropped.join(', ')}`);
  if (notIn.length && SpecCtrl.canEdit()) parts.push(`belum masuk revisi: ${notIn.join(', ')}`);
  return parts.join(' · ');
}

