      u16(central, 20);
      u16(central, 20);
      u16(central, 0x0800);
      u16(central, 0);
      u16(central, time);
      u16(central, date);
      u32(central, crc);
      u32(central, data.length);
      u32(central, data.length);
      u16(central, name.length);
      u16(central, 0);
      u16(central, 0);
      u16(central, 0);
      u16(central, 0);
      u32(central, 0);
      u32(central, offset);
      copy(central, name);
    });
    const cdOffset = out.length;
    copy(out, central);
    u32(out, 0x06054B50);
    u16(out, 0);
    u16(out, 0);
    u16(out, entries.length);
