actionConfiguration.body:
async function (logId, images) {
  if (!images.length) return 0;
  let failed = 0;
  SpecCtrl.pubBusy = true;
  for (const img of images) {
    try {
      await a_change_log_attach.run({
        log_id: logId,
        file_name: img.name || 'gambar',
        data: img.data || ''
      });
    } catch (e) {
      failed += 1;
    }
  }
  SpecCtrl.pubBusy = false;
  return failed;
}

