  const a = CbdCtrl.article();
  const r = CbdCtrl.revision();
  if (!m || !s || !a || !r) return showAlert('Buka revisi CBD dulu.', 'warning');
  CbdExportCtrl.busy = true;
  CbdExportCtrl.step = 'menyusun isi';
  try {
    const wb = CbdExportCtrl.build(m, s, a, r);
