actionConfiguration.body:
function (m, s, a, r) {
  const N = 15;
  const lines = CbdGridCtrl.lines();
  const rc = CbdGridCtrl.recap() || ({});
  const items = CbdGridCtrl.costItems();
  const log = r.status === 'PUBLISHED' ? CbdCtrl.logFor(r.id) : null;
  const rate = CbdExportCtrl.n(r.exchange_rate);
  const wb = XlsxWriter.workbook();
  wb.creator = Auth.me && Auth.me.full_name || '';
  wb.created = new Date();
  const ws = wb.addWorksheet(`${a.code} ${r.stage} r${r.revision_no}`.slice(0, 31), {
    pageSetup: {
      orientation: 'landscape',
      paperSize: 9,
      fitToPage: true,
      fitToWidth: 1,
      fitToHeight: 0
    }
  });
  [6, 24, 34, 11, 9, 18, 10, 10, 8, 13, 15, 17, 18, 20, 16].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
  ws.getCell('A1').value = 'Cost Breakdown Sheet';
  ws.getCell('A1').font = {
    bold: true,
    size: 16,
    color: {
      argb: CbdExportCtrl.NAVY
    }
  };
  ws.getCell('A2').value = 'Confidential Information';
  ws.getCell('A2').font = {
    italic: true,
    color: {
      argb: 'FF6B7280'
    }
  };
  ws.getCell('K2').value = 'Tanggal';
  ws.getCell('L2').value = new Date(r.status === 'PUBLISHED' && r.published_at ? r.published_at : Date.now());
  ws.getCell('L2').numFmt = 'dd-mmm-yyyy';
  ws.getCell('K3').value = '1 $ =';
  ws.getCell('K3').alignment = {
    horizontal: 'right'
  };
  ws.getCell('L3').value = rate;
  ws.getCell('L3').numFmt = CbdExportCtrl.RP;
  ws.getCell('L3').font = {
    bold: true,
    size: 14
  };
  const v = x => x || '-';
  const info = [['Model Name', `${m.code} — ${m.name}; Mold: ${v(m.outsole_mold)}; Last: ${v(m.last_no)}; Size Range: ${v(m.size_range)}`], ['Article #', `${a.code}`], ['Construction', v(m.construction)], ['Color', v(a.colorway)], ['Season / Revisi', `${s.season} · ${r.stage} r${r.revision_no} · ${r.status}` + (r.status === 'PUBLISHED' ? ` · terbit oleh ${r.published_by || '-'}` : ' · BELUM TERBIT') + ` · acuan specsheet ${r.spec_label || '-'}`]];
  info.forEach(([k, val], i) => {
    ws.getCell(`B${4 + i}`).value = k;
    ws.getCell(`B${4 + i}`).font = {
      bold: true
    };
    ws.getCell(`C${4 + i}`).value = val;
  });
  ws.getCell('C8').font = {
    bold: true,
    color: {
      argb: r.status === 'PUBLISHED' ? 'FF16A34A' : 'FFDC2626'
    }
  };
  const h1 = ws.getRow(10);
  const h2 = ws.getRow(11);
  ['No', 'Component Name', 'Material description', 'Thickness', 'Unit', 'Color', 'Yield', 'Usage', 'Loss %', 'Unit Price', '', 'Cost/pr (Rp)', 'Supplier', 'Remarks', 'Asal'].forEach((t, i) => {
    h1.getCell(i + 1).value = t;
  });
  h2.getCell(10).value = 'USD';
  h2.getCell(11).value = 'IDR';
  ws.mergeCells('J10:K10');
  [1, 2, 3, 4, 5, 6, 7, 8, 9, 12, 13, 14, 15].forEach(c => ws.mergeCells(10, c, 11, c));
  [h1, h2].forEach(row => {
    CbdExportCtrl.fill(row, 1, N, CbdExportCtrl.NAVY);
    CbdExportCtrl.box(row, 1, N);
    for (let c = 1; c <= N; c++) {
      row.getCell(c).font = {
        bold: true,
        color: {
          argb: 'FFFFFFFF'
        }
      };
      row.getCell(c).alignment = {
        horizontal: 'center',
        vertical: 'middle',
        wrapText: true
      };
    }
  });
  const writeLine = (l, counted) => {
    const row = ws.addRow([]);
    const i = row.number;
    const y = CbdExportCtrl.n(l.yield_value);
    const p = CbdExportCtrl.n(l.price_original);
    row.getCell(1).value = l.is_sub ? '' : l.display_no || '';
    row.getCell(2).value = (l.is_sub ? '↳ ' : '') + (l.display_name || '') + (l.is_local ? ' (lokal)' : '');
    row.getCell(3).value = `${l.material_name || ''}${l.material_code ? ' [' + l.material_code + ']' : ''}`;
    row.getCell(4).value = l.thickness || '';
    row.getCell(5).value = l.uom || '';
    row.getCell(6).value = l.color || '';
    row.getCell(7).value = y;
    row.getCell(8).value = y ? CbdExportCtrl.f(`1/G${i}`, CbdExportCtrl.n(l.usage_value)) : null;
    row.getCell(9).value = CbdExportCtrl.n(l.loss_pct) ?? 0;
    if (p !== null && l.currency === 'USD') {
      row.getCell(10).value = p;
      row.getCell(11).value = CbdExportCtrl.f(`J${i}*$L$3`, CbdExportCtrl.n(l.price_idr));
    } else if (p !== null) {
      row.getCell(11).value = p;
    }
    if (counted && y && p !== null && (l.currency === 'IDR' || rate)) {
      row.getCell(12).value = CbdExportCtrl.f(`H${i}*(1+I${i}/100)*K${i}`, CbdExportCtrl.n(l.cost_per_pair));
    }
    row.getCell(13).value = l.supplier_name || '';
    row.getCell(14).value = l.remarks || '';
    const src = ({
      MASTER: 'harga master',
      OVERRIDE: 'override',
      QUOTATION: 'quotation'
    })[l.price_source] || 'tanpa harga';
    const org = ({
      INPUT: '',
      COPIED: ' · copy',
      CARRIED_FROM_REPLACED: ' · ganti material'
    })[l.value_origin] || '';
    row.getCell(15).value = src + org + (l.price_source === 'OVERRIDE' && l.price_override_reason ? `: ${l.price_override_reason}` : '');
    row.getCell(7).numFmt = '#,##0.00####';
    row.getCell(8).numFmt = '0.000000';
    row.getCell(9).numFmt = '0.00';
    row.getCell(10).numFmt = CbdExportCtrl.USD;
    row.getCell(11).numFmt = CbdExportCtrl.RP;
    row.getCell(12).numFmt = CbdExportCtrl.RP;
    CbdExportCtrl.box(row, 1, N);
    for (let c = 1; c <= N; c++) row.getCell(c).alignment = {
      vertical: 'top',
      wrapText: c <= 6 || c >= 13
    };
    if (!counted) for (let c = 1; c <= N; c++) row.getCell(c).font = {
      color: {
        argb: 'FF9CA3AF'
      }
    };
    return i;
  };
  const groupHeader = (label, argb) => {
    const row = ws.addRow([label]);
    ws.mergeCells(row.number, 1, row.number, N);
    row.getCell(1).font = {
      bold: true,
      color: {
        argb: CbdExportCtrl.NAVY
      }
    };
    CbdExportCtrl.fill(row, 1, N, argb);
  };
  const active = lines.filter(l => l.status === 'ACTIVE');
  const missing = lines.filter(l => l.status !== 'ACTIVE');
  const groups = [];
  active.forEach(l => {
    let g = groups[groups.length - 1];
    if (!g || g.code !== l.group_code) groups.push(g = {
      code: l.group_code,
      name: l.group_name,
      lines: []
    });
    g.lines.push(l);
  });
  const subtotalCells = [];
  const gc = rc.group_costs || ({});
  groups.forEach(g => {
    groupHeader(`${String(g.code || '').toLowerCase()}. ${g.name || ''}`, CbdExportCtrl.GROUP_FILL);
    const rows = g.lines.map(l => writeLine(l, true));
    const st = ws.addRow([]);
    st.getCell(2).value = `Subtotal ${String(g.code || '').toUpperCase()} · ${g.name || ''}`;
    st.getCell(12).value = CbdExportCtrl.f(`SUM(L${rows[0]}:L${rows[rows.length - 1]})`, CbdExportCtrl.n(gc[g.code]) ?? 0);
    st.getCell(12).numFmt = CbdExportCtrl.RP;
    st.font = {
      bold: true
    };
    CbdExportCtrl.box(st, 1, N);
    subtotalCells.push(`L${st.number}`);
    ws.addRow([]);
  });
  if (!groups.length) ws.addRow(['Belum ada baris CBD.']);
  if (missing.length) {
    groupHeader(`Hilang dari specsheet (MISSING_IN_SPEC) — ${missing.length} baris, tidak dihitung`, CbdExportCtrl.MISSING_FILL);
    missing.forEach(l => writeLine(l, false));
    ws.addRow([]);
  }
  ws.addRow([]);
  const title = ws.addRow([]);
  title.getCell(7).value = 'Cost recapitulation';
  title.getCell(7).font = {
    bold: true,
    size: 12,
    color: {
      argb: CbdExportCtrl.NAVY
    }
  };
  const recapRow = (label, value, note, bold) => {
    const row = ws.addRow([]);
    row.getCell(7).value = label;
    row.getCell(12).value = value;
    row.getCell(12).numFmt = CbdExportCtrl.RP;
    if (note) row.getCell(13).value = note;
    if (bold) row.font = {
      bold: true
    };
    ws.mergeCells(row.number, 7, row.number, 11);
    CbdExportCtrl.box(row, 7, 13);
    return row.number;
  };
  const letter = i => String.fromCharCode(97 + i) + '.';
  const first = recapRow(`${letter(0)} Material Cost`, CbdExportCtrl.f(subtotalCells.length ? `SUM(${subtotalCells.join(',')})` : '0', CbdExportCtrl.n(rc.material_cost) ?? 0), '', true);
  let last = first;
  items.forEach((it, i) => {
    last = recapRow(`${letter(i + 1)} ${it.name || CbdExportCtrl.COST_LABEL[it.item_type]}`, CbdExportCtrl.n(it.amount) ?? 0, it.remarks || '');
  });
  const fobRow = recapRow('ACTUAL FOB', CbdExportCtrl.f(`SUM(L${first}:L${last})`, CbdExportCtrl.n(rc.actual_fob)), 'material cost + semua biaya', true);
  ws.getRow(fobRow).getCell(12).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: {
      argb: CbdExportCtrl.GROUP_FILL
    }
  };
  ws.addRow([]);
  const tRow = ws.addRow([]);
  tRow.getCell(11).value = 'TARGET FOB';
  tRow.getCell(12).value = CbdExportCtrl.n(rc.target_fob);
  tRow.getCell(12).numFmt = CbdExportCtrl.RP;
  const t = tRow.number;
  const vRow = ws.addRow([]);
  if (tRow.getCell(12).value !== null) {
    vRow.getCell(11).value = CbdExportCtrl.f(`IF(L${fobRow}>L${t},"OVER",IF(L${fobRow}<L${t},"UNDER","SESUAI"))`, rc.variance_label || null);
    vRow.getCell(12).value = CbdExportCtrl.f(`L${fobRow}-L${t}`, CbdExportCtrl.n(rc.variance));
    vRow.getCell(12).numFmt = CbdExportCtrl.RP;
    vRow.getCell(11).font = {
      bold: true,
      color: {
        argb: rc.variance_label === 'OVER' ? 'FFDC2626' : 'FF16A34A'
      }
    };
  }
  [tRow, vRow].forEach(row => {
    row.getCell(11).alignment = {
      horizontal: 'right'
    };
  });
  ws.addRow([]);
  const sTitle = ws.addRow([]);
  sTitle.getCell(11).value = 'Harga jual';
  sTitle.getCell(11).font = {
    bold: true,
    size: 12,
    color: {
      argb: CbdExportCtrl.NAVY
    }
  };
  const spRow = ws.addRow([]);
  spRow.getCell(11).value = 'Selling price';
  spRow.getCell(12).value = CbdExportCtrl.n(rc.selling_price);
  spRow.getCell(12).numFmt = CbdExportCtrl.RP;
  const mRow = ws.addRow([]);
  mRow.getCell(11).value = 'Margin %';
  if (spRow.getCell(12).value) {
    mRow.getCell(12).value = CbdExportCtrl.f(`(L${spRow.number}-L${fobRow})/L${spRow.number}*100`, CbdExportCtrl.n(rc.margin_pct));
  }
  mRow.getCell(12).numFmt = '0.00';
  [spRow, mRow].forEach(row => {
    CbdExportCtrl.box(row, 11, 12);
    row.getCell(11).alignment = {
      horizontal: 'right'
    };
  });
  if (log) {
    ws.addRow([]);
    const c = ws.addRow(['', 'Change log']);
    c.getCell(2).font = {
      bold: true
    };
    const ch = ws.addRow(['', 'Tanggal', 'Kategori', 'Oleh', '', 'Alasan']);
    ch.font = {
      bold: true
    };
    ws.addRow(['', moment(log.created_at).format('DD-MM-YYYY HH:mm'), log.category, log.created_by, '', log.reason]);
  }
  ws.views = [{
    state: 'frozen',
    xSplit: 3,
    ySplit: 11
  }];
  return wb;
}

