async function (query, params) {
  CbdGridCtrl.busyCount = CbdGridCtrl.busyCount + 1;
  try {
    await query.run(params);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return false;
    }
    CbdGridCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    await CbdGridCtrl.reload();
    return false;
  } finally {
    CbdGridCtrl.busyCount = Math.max(0, CbdGridCtrl.busyCount - 1);
  }
  CbdGridCtrl.message = null;
  await CbdGridCtrl.reload();
  return true;
}

