actionConfiguration.body:
async function () {
  const f = cwCbdPriceForm.model || ({});
  const l = CbdGridCtrl.priceLine();
  if (!l) return;
  const q = CbdGridCtrl.priceMode === 'QUOTATION';
  CbdGridCtrl.priceMsg = null;
  CbdGridCtrl.priceBusy = true;
  try {
    if (q) {
      await a_cbd_set_quotation.run({
        line_id: l.id,
        price: f.price || '',
        currency: f.currency || '',
        reference: f.text || ''
      });
    } else {
      await a_cbd_override_price.run({
        line_id: l.id,
        price: f.price || '',
        currency: f.currency || '',
        reason: f.text || ''
      });
    }
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlCbdHarga');
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    CbdGridCtrl.priceMsg = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    CbdGridCtrl.priceBusy = false;
  }
  closeModal('mdlCbdHarga');
  showAlert(q ? f.price ? 'Harga quotation disimpan.' : 'Harga quotation dikosongkan.' : 'Override harga disimpan.', 'success');
  CbdGridCtrl.message = null;
  await CbdGridCtrl.reload();
}

