actionConfiguration.body:
async function () {
  const f = cwPublishForm.model || ({});
  const images = Array.isArray(f.images) ? f.images : [];
  const r = CbdCtrl.revision();
  if (!r) return;
  CbdCtrl.pubMsg = null;
  CbdCtrl.pubBusy = true;
  try {
    await a_cbd_publish.run({
      revision_id: r.id,
      category: f.category || '',
      reason: f.reason || ''
    });
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlCbdTerbit');
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    CbdCtrl.pubMsg = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    CbdCtrl.pubBusy = false;
  }
  const logId = ((a_cbd_publish.data || [])[0] || ({})).id;
  const failed = await CbdCtrl.attachImages(logId, images);
  closeModal('mdlCbdTerbit');
  showAlert(`CBD ${CbdCtrl.label(r)} diterbitkan.` + (failed ? ` ${failed} gambar gagal dilampirkan.` : images.length ? ` ${images.length} gambar dilampirkan.` : ''), failed ? 'warning' : 'success');
  await CbdCtrl.refresh(r.id);
}

