actionConfiguration.body:
function () {
  const r = CbdCtrl.revision();
  const a = CbdCtrl.article();
  if (!r || r.status !== 'DRAFT' || !a || !CbdCtrl.canEdit()) return [];
  const out = [];
  if (a.draft_stale) {
    out.push({
      tone: 'danger',
      action: 'refreshSpec',
      actionLabel: 'Refresh dari Specsheet',
      text: `Specsheet sudah terbit ${a.spec_pub_label} — baris draft ini masih dari ${r.spec_label}. ` + 'Refresh dulu sebelum terbit (Yield, Loss % & harga input dibawa; baris yang hilang jadi MISSING_IN_SPEC).'
    });
    return out;
  }
  const lines = CbdGridCtrl.lines().filter(l => l.status === 'ACTIVE');
  const stale = lines.filter(l => l.master_stale).length;
  if (stale) {
    out.push({
      tone: 'warn',
      action: 'refreshPrices',
      actionLabel: 'Refresh Harga dari Master',
      text: `Harga master untuk ${stale} baris baru tersedia atau berubah sejak CBD ini dibuat. ` + 'Samakan dulu sebelum terbit.'
    });
  }
  const gaps = lines.filter(l => ['NO_PRICE', 'NO_COLOR_PRICE', 'PENDING'].includes(l.price_gap)).length;
  const noSup = lines.filter(l => l.price_gap === 'NO_SUPPLIER').length;
  const parts = [];
  if (gaps) parts.push(`${gaps} baris belum punya harga master (isi di Master Material, lalu Refresh Harga) — boleh terbit dengan cost 0.`);
  if (noSup) parts.push(`${noSup} baris belum punya supplier di specsheet.`);
  if (parts.length) out.push({
    tone: 'info',
    text: parts.join(' ')
  });
  const rc = CbdGridCtrl.recap();
  if (rc && rc.usd_no_rate_count) {
    out.push({
      tone: 'warn',
      text: `${rc.usd_no_rate_count} baris berharga USD belum terhitung — isi Exchange rate di rekap.`
    });
  }
  return out;
}

