actionConfiguration.body:
async function () {
  const a = (cwCbdGrid.model || ({})).action;
  if (!a || !a.type) return;
  const r = CbdCtrl.revision();
  if (!r) return;
  switch (a.type) {
    case 'setYield':
    case 'setLoss':
      await CbdGridCtrl.exec(a_cbd_line_set, {
        line_id: a.line_id,
        field: a.type === 'setYield' ? 'YIELD' : 'LOSS',
        value: a.value ?? ''
      });
      break;
    case 'setHeader':
      await CbdGridCtrl.exec(a_cbd_header_set, {
        revision_id: r.id,
        field: a.field,
        value: a.value ?? ''
      });
      break;
    case 'addCost':
      if (await CbdGridCtrl.exec(a_cbd_cost_add, {
        revision_id: r.id,
        item_type: a.item_type,
        name: a.name || '',
        amount: a.amount ?? '',
        remarks: a.remarks || ''
      })) CbdGridCtrl.costOkKey = CbdGridCtrl.costOkKey + 1;
      break;
    case 'setCost':
      await CbdGridCtrl.exec(a_cbd_cost_set, {
        item_id: a.item_id,
        field: a.field,
        value: a.value ?? ''
      });
      break;
    case 'deleteCost':
      await CbdGridCtrl.exec(a_cbd_cost_delete, {
        item_id: a.item_id
      });
      break;
    case 'editPrice':
      CbdGridCtrl.openPrice(a.line_id, a.mode);
      break;
    case 'clearOverride':
      if (await CbdGridCtrl.exec(a_cbd_clear_override, {
        line_id: a.line_id
      })) showAlert('Override dihapus — kembali ke harga master.', 'success');
      break;
    case 'refreshPrices':
      if (await CbdGridCtrl.exec(a_cbd_refresh_prices, {
        revision_id: r.id
      })) {
        const n = a_cbd_refresh_prices.data && a_cbd_refresh_prices.data[0] && a_cbd_refresh_prices.data[0].n;
        showAlert(`Harga ${n || ''} baris disamakan dengan master.`, 'success');
      }
      break;
    case 'refreshSpec':
      if (await CbdGridCtrl.exec(a_cbd_refresh_spec, {
        revision_id: r.id
      })) {
        showAlert('CBD di-refresh dari specsheet terbit terakhir.', 'success');
        await CbdCtrl.refresh(r.id);
      }
      break;
  }
}

