      await CbdGridCtrl.exec(a_cbd_line_set, {
        line_id: a.line_id,
        field: a.type === 'setYield' ? 'YIELD' : 'LOSS',
        value: a.value ?? ''
      });
      break;
    case 'setHeader':
      await CbdGridCtrl.exec(a_cbd_header_set, {
        revision_id: r.id,
        field: a.field,
        value: a.value ?? ''
      });
      break;
    case 'addCost':
      if (await CbdGridCtrl.exec(a_cbd_cost_add, {
        revision_id: r.id,
        item_type: a.item_type,
        name: a.name || '',
        amount: a.amount ?? '',
        remarks: a.remarks || ''
      })) CbdGridCtrl.costOkKey = CbdGridCtrl.costOkKey + 1;
      break;
    case 'setCost':
      await CbdGridCtrl.exec(a_cbd_cost_set, {
        item_id: a.item_id,
        field: a.field,
        value: a.value ?? ''
      });
      break;
    case 'deleteCost':
      await CbdGridCtrl.exec(a_cbd_cost_delete, {
        item_id: a.item_id
      });
      break;
    case 'editPrice':
      CbdGridCtrl.openPrice(a.line_id, a.mode);
      break;
    case 'clearOverride':
      if (await CbdGridCtrl.exec(a_cbd_clear_override, {
        line_id: a.line_id
      })) showAlert('Override dihapus — kembali ke harga master.', 'success');
      break;
    case 'refreshPrices':
      if (await CbdGridCtrl.exec(a_cbd_refresh_prices, {
        revision_id: r.id
      })) {
        const n = a_cbd_refresh_prices.data && a_cbd_refresh_prices.data[0] && a_cbd_refresh_prices.data[0].n;
        showAlert(`Harga ${n || ''} baris disamakan dengan master.`, 'success');
      }
      break;
    case 'refreshSpec':
      if (await CbdGridCtrl.exec(a_cbd_refresh_spec, {
        revision_id: r.id
      })) {
        showAlert('CBD di-refresh dari specsheet terbit terakhir.', 'success');
        await CbdCtrl.refresh(r.id);
      }
      break;
  }
}

actionConfiguration.body:
function () {
  const a = CbdCtrl.article();
  const latest = CbdCtrl.latestPublished();
  const specLabel = a && a.spec_pub_label ? a.spec_pub_label : '';
  let options = [];
  let sources = [];
  if (a && !CbdCtrl.revisions().length) {
    sources = (q_cbd_sources.data || []).map(s => ({
      id: s.id,
      label: `${s.code} · ${s.season} · ${s.label} terbit${s.dropped ? ' · di-drop' : ''}`
    }));
    options = [{
      v: 'NEW',
      title: 'CBD baru dari specsheet',
      desc: `Baris dari specsheet ${specLabel}; harga dari master harga. Yield & Loss % diisi.`
    }, {
      v: 'COPY',
      title: 'Copy dari article lain (model sama)',
      needsSource: true,
      disabled: !sources.length,
      desc: sources.length ? 'Baris, warna & supplier tetap dari specsheet article ini; yang di-copy Yield, Loss %, harga quotation/override, dan rekap.' : 'Belum ada article lain model ini yang punya CBD terbit.'
    }];
  } else if (a && latest) {
    const revs = CbdCtrl.revisions().filter(r => r.stage === a.spec_pub_stage);
    const no = revs.length ? Math.max(...revs.map(r => r.revision_no)) + 1 : 0;
    options = [{
      v: 'NEXT',
      title: `Revisi berikutnya: ${a.spec_pub_stage} r${no}`,
      desc: `Baris dari specsheet ${specLabel}; Yield, Loss %, harga input & rekap dari ${CbdCtrl.label(latest)}. ` + 'Baris yang tidak ada lagi di specsheet ditandai MISSING_IN_SPEC.'
    }];
  }
  return {
    key: CbdCtrl.createKey,
    title: a ? `Buat CBD — ${a.code} · ${a.colorway}` : 'Buat CBD',
    note: specLabel ? `Acuan: specsheet ${CbdCtrl.season() ? CbdCtrl.season().season + ' ' : ''}${specLabel} (terbit terakhir).` : '',
    options,
    sources,
    emptyText: 'Terbitkan atau hapus draft yang ada dulu sebelum membuat revisi baru.',
    busy: CbdCtrl.createBusy,
    message: CbdCtrl.createMsg
  };
}

