actionConfiguration.body:
function (a) {
  if (a.spec_status === 'DROPPED') return {
    badge: a.pub_label ? `DI-DROP · ${a.pub_label}` : 'DI-DROP',
    tone: 'muted'
  };
  if (a.draft_id) return {
    badge: `DRAFT ${a.draft_label}${a.draft_stale ? ' · specsheet baru' : ''}`,
    tone: 'draft'
  };
  if (a.pub_id && a.pub_sync === 'NEEDS_REVISION') return {
    badge: `PERLU REVISI · ${a.pub_label}`,
    tone: 'danger'
  };
  if (a.pub_id) return {
    badge: `TERBIT ${a.pub_label}`,
    tone: 'ok'
  };
  if (a.spec_status === 'NOT_PUBLISHED') return {
    badge: 'SPECSHEET BELUM TERBIT',
    tone: 'muted'
  };
  return {
    badge: 'BELUM ADA CBD',
    tone: 'info'
  };
}

