actionConfiguration.body:
function () {
  const l = CbdGridCtrl.priceLine();
  const q = CbdGridCtrl.priceMode === 'QUOTATION';
  const fmt = (v, cur) => `${Util.fmtNum(v, cur === 'USD' ? 4 : 2)} ${cur || ''}`.trim();
  let current = '';
  let info = '';
  if (l) {
    if (l.price_original != null) {
      const src = ({
        MASTER: 'harga master',
        OVERRIDE: 'override',
        QUOTATION: 'quotation'
      })[l.price_source] || '';
      current = `Harga sekarang: ${fmt(l.price_original, l.currency)}${src ? ' (' + src + ')' : ''}`;
    } else {
      current = 'Harga sekarang: kosong';
    }
    if (!q && l.master_price != null && l.price_source !== 'MASTER') info = `Harga master berlaku: ${fmt(l.master_price, l.master_currency)}.`;
    if (!q && l.price_gap === 'PENDING') info = 'Ada usulan harga master yang menunggu approval Manager Costing — setelah di-approve, klik Refresh Harga.';
  }
  return {
    key: CbdGridCtrl.priceKey,
    mode: CbdGridCtrl.priceMode,
    title: q ? 'Harga Quotation' : 'Override Harga',
    lineLabel: l ? [l.display_no, l.display_name, `${l.material_code} ${l.material_name}`, l.color, l.supplier_name].filter(x => x).join(' · ') : '',
    current,
    form: {
      price: l && l.price_source === (q ? 'QUOTATION' : 'OVERRIDE') && l.price_original != null ? String(Number(l.price_original)) : '',
      text: l ? q ? l.price_reference || '' : l.price_source === 'OVERRIDE' ? l.price_override_reason || '' : '' : ''
    },
    info,
    busy: CbdGridCtrl.priceBusy,
    message: CbdGridCtrl.priceMsg
  };
}

