actionConfiguration.body:
async function () {
  const f = cwCbdForm.model || ({});
  const a = CbdCtrl.article();
  if (!a) return;
  CbdCtrl.createMsg = null;
  CbdCtrl.createBusy = true;
  try {
    await a_cbd_create.run({
      article_id: a.id,
      mode: f.mode || '',
      source_article_id: f.source_article_id || ''
    });
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlCbdBaru');
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    CbdCtrl.createMsg = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    CbdCtrl.createBusy = false;
  }
  closeModal('mdlCbdBaru');
  const id = a_cbd_create.data && a_cbd_create.data[0] && a_cbd_create.data[0].id;
  showAlert('CBD draft dibuat.', 'success');
  await CbdCtrl.refresh(id);
}

