function () {
  const r = CbdCtrl.revision();
  const a = CbdCtrl.article();
  const c = q_cbd_checklist.data && q_cbd_checklist.data[0] || null;
  const checks = !c ? [] : [{
    label: 'Specsheet acuan = terbit terakhir',
    ok: !c.spec_stale,
    blocking: true,
    detail: c.spec_stale ? 'Klik "Refresh dari Specsheet" di atas grid' : ''
  }, {
    label: 'Exchange rate terisi',
    ok: !!c.rate_ok,
    blocking: true,
    detail: c.rate_ok ? '' : 'Isi Exchange rate di rekap'
  }, {
    label: 'Harga master sama dengan master terkini',
    ok: c.stale_prices === 0,
    blocking: true,
    detail: c.stale_prices ? `${c.stale_prices} baris berubah — klik "Refresh Harga dari Master"` : ''
  }, {
    label: 'Baris berharga punya Yield',
    ok: c.no_yield_count === 0,
    blocking: true,
    detail: c.no_yield_count ? `${c.no_yield_count} baris belum diisi Yield (kotak kuning)` : ''
  }, {
    label: 'Semua baris berharga',
    ok: c.unpriced_count === 0,
    blocking: false,
    detail: c.unpriced_count ? `${c.unpriced_count} baris tanpa harga akan terbit dengan cost 0` : ''
  }];
  if (c && c.spec_status !== 'ACTIVE') {
    checks.unshift({
      label: 'Article aktif di specsheet terbit',
      ok: false,
      blocking: true,
      detail: 'Article di-drop / belum terbit — CBD ini tidak bisa diterbitkan'
    });
  }
  const requiresReason = c ? !!c.requires_reason : true;
  return {
    key: CbdCtrl.pubKey,
    title: `Terbitkan CBD ${a ? a.code + ' · ' : ''}${CbdCtrl.label(r)}`,
    checks,
    blocked: !c || !!c.blocked,
    blockedWhere: 'di grid / rekap CBD',
    requiresReason,
    categories: CbdCtrl.CATEGORIES,
    defaultCategory: requiresReason ? '' : 'OTHER',
    maxImages: 5,
    busy: CbdCtrl.pubBusy,
    message: CbdCtrl.pubMsg
  };
}

