async function () {
  try {
    await q_cbd_models.run();
  } catch (e) {
    showAlert(Util.cleanError(e && e.message), 'error');
  }
  const url = appsmith.URL.queryParams;
  if (CbdCtrl.firstLoad) CbdCtrl.from = url.from || '';
  const want = CbdCtrl.modelId || (CbdCtrl.firstLoad ? url.model_id : '');
  CbdCtrl.modelId = CbdCtrl.models().some(m => m.id === want) ? want : '';
  if (want && !CbdCtrl.modelId) showAlert('Model tidak ditemukan. Pilih model di atas.', 'warning');
  await CbdCtrl.loadModel(CbdCtrl.firstLoad ? url.season : CbdCtrl.seasonId, CbdCtrl.firstLoad ? url.article : '');
  CbdCtrl.firstLoad = false;
}

