async function () {
  const oldPass = cwLogin.model.oldPass || '';
  const newPass = cwLogin.model.newPass || '';
  if (!oldPass || !newPass) {
    LoginCtrl.setMessage('error', 'Isi password lama dan password baru.');
    return;
  }
  LoginCtrl.setMessage(null);
  LoginCtrl.busy = true;
  try {
    await a_change_password.run({
      oldPass,
      newPass
    });
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      await removeValue('token');
      LoginCtrl.view = 'login';
      LoginCtrl.forced = false;
      LoginCtrl.setMessage('error', 'Sesi login habis. Silakan login lagi.');
    } else {
      LoginCtrl.setMessage('error', Util.cleanError(msg));
    }
    return;
  } finally {
    LoginCtrl.busy = false;
  }
  showAlert('Password berhasil diganti.', 'success');
  LoginCtrl.goHome();
}

