		const text = String((cwSupplierForm.model || {}).similarQuery || '').trim();
		const seq = SupplierCtrl.similarSeq + 1;
		SupplierCtrl.similarSeq = seq;
		if (text.length < 2) {
			SupplierCtrl.similar = [];
			SupplierCtrl.similarFor = text;
			return;
		}
		try {
			const rows = await q_similar.run({ kind: 'SUPPLIER', text, exclude_id: SupplierCtrl.form.id || '' });
			if (seq !== SupplierCtrl.similarSeq) return;
			SupplierCtrl.similar = rows || [];
			SupplierCtrl.similarFor = text;
		} catch (e) {
			/* daftar mirip hanya bantuan — abaikan */
		}
	}

