		const f = cwVariantForm.model || {};
		const isNew = MaterialDetailCtrl.varIsNew;
		const ok = isNew
			? await MaterialDetailCtrl.runForm(a_variant_add, { material_id: appsmith.URL.queryParams.id, items: f.items || [] },
				v => { MaterialDetailCtrl.varMsg = v; }, v => { MaterialDetailCtrl.varBusy = v; }, 'mdlVarian')
			: await MaterialDetailCtrl.runForm(a_variant_update, {
				id: MaterialDetailCtrl.varForm.id, thickness_mm: f.thickness_mm, color: f.color, code: f.code, status: f.status,
			}, v => { MaterialDetailCtrl.varMsg = v; }, v => { MaterialDetailCtrl.varBusy = v; }, 'mdlVarian');
		if (!ok) return;
		closeModal('mdlVarian');
		showAlert(isNew ? `${(f.items || []).length} varian ditambahkan.` : 'Varian disimpan.', 'success');
		await MaterialDetailCtrl.refresh([q_variants, q_material]);
	}

