actionConfiguration.body:
async function () {
		// Baca model dulu — model di-reset saat state (Default model) berubah
		const m = cwOptionForm.model || {};
		const data = {
			id: OptionCtrl.form.id || '',
			kind: OptionCtrl.form.kind || OptionCtrl.kind(),
			value: String(m.value || '').trim(),
			sort_order: m.sort_order === undefined || m.sort_order === null ? '' : String(m.sort_order),
			status: OptionCtrl.isNew ? 'ACTIVE' : m.status,
		};
		if (!data.value) {
			OptionCtrl.message = { type: 'error', text: 'Nilai wajib diisi.' };
			return;
		}
		OptionCtrl.message = null;
		OptionCtrl.busy = true;
		try {
			await a_option_save.run(data);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlPilihan');
				await removeValue('token');
				showAlert('Sesi login habis. Silakan login lagi.', 'warning');
				navigateTo('Login');
				return;
			}
			OptionCtrl.message = { type: 'error', text: Util.cleanError(msg) };
			return;
		} finally {
			OptionCtrl.busy = false;
		}
		closeModal('mdlPilihan');
