				items: s ? [{
					title: `${n(s.materials)} material · ${n(s.articles)} article · ${n(s.active_users)} user aktif`,
					meta: `Aktivitas terakhir ${Util.fmtDateTime(s.last_audit)}. Buka menu Admin untuk user dan audit log.`,
